-- Generated by tools/generate.py from bricksurance-data-core model v0.15.0.
-- Do not edit: change the spec in model/ and regenerate.

CREATE OR REPLACE VIEW lr_serverless_aws_us_catalog.bricksurance_renewal.renewal_metrics
COMMENT 'Retention KPIs over renewal cases - retention rate, average price walk and the premium lost to lapse, by line, price-walk band and currency. This is the loop''s scoreboard: as renewal prices change, retention and lapse value move. Query measures with MEASURE(name).'
WITH METRICS
LANGUAGE YAML
AS $$
version: 0.1

source: lr_serverless_aws_us_catalog.bricksurance_renewal.renewal_case

joins:
  - name: policy
    source: lr_serverless_aws_us_catalog.bricksurance_policy.policy
    on: source.policy_id = policy.policy_id

dimensions:
  - name: line_of_business_code
    expr: policy.line_of_business_code
  - name: price_walk_band
    expr: CASE WHEN source.price_walk_pct < 0.05 THEN '0-5%' WHEN source.price_walk_pct < 0.10 THEN '5-10%' WHEN source.price_walk_pct < 0.20 THEN '10-20%' ELSE '20%+' END
  - name: renewal_outcome_code
    expr: source.renewal_outcome_code
  - name: currency_code
    expr: source.currency_code

measures:
  - name: case_count
    expr: COUNT(renewal_case_id)
  - name: renewed_count
    expr: COUNT(CASE WHEN renewal_outcome_code = 'RENEWED' THEN renewal_case_id END)
  - name: lapsed_count
    expr: COUNT(CASE WHEN renewal_outcome_code IN ('LAPSED_PRICE', 'LAPSED_OTHER') THEN renewal_case_id END)
  - name: retention_rate
    expr: COUNT(CASE WHEN renewal_outcome_code = 'RENEWED' THEN renewal_case_id END) / NULLIF(COUNT(renewal_case_id), 0)
  - name: avg_price_walk
    expr: AVG(price_walk_pct)
  - name: lapse_gwp
    expr: SUM(CASE WHEN renewal_outcome_code IN ('LAPSED_PRICE', 'LAPSED_OTHER') THEN prior_premium ELSE 0 END)
$$;
